package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.internal.util.Checks;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMetadataSupport_actualTypeArguments_TriageGen2Test {

    private GenericMetadataSupport genericMetadataSupport;

    @Before
    public void setUp() {
        // Since GenericMetadataSupport is an abstract class (implied by abstract rawType()),
        // we mock it to test the concrete method actualTypeArguments().
        genericMetadataSupport = mock(GenericMetadataSupport.class, Mockito.CALLS_REAL_METHODS);
    }

    @Test
    public void testActualTypeArguments_EmptyParameters() {
        // Arrange
        TypeVariable[] emptyParams = new TypeVariable[0];
        when(genericMetadataSupport.rawType()).thenReturn(String.class);
        doReturn(emptyParams).when(genericMetadataSupport).rawType().getTypeParameters(); 
        // Note: In a real mock scenario, we need to handle the chain. 
        // However, since rawType() is abstract, we mock the call.

        // Re-mocking to handle the internal call structure correctly for the method under test
        when(genericMetadataSupport.rawType()).thenReturn(String.class);
        // We must mock the behavior of rawType().getTypeParameters()
        // But rawType() returns Class, and Class.getTypeParameters() is final.
        // In this specific test environment, we assume rawType() returns a class with 0 params.

        // Let's use a more robust approach for mocking the abstract method dependencies
        Class<?> mockClass = String.class; 
        when(genericMetadataSupport.rawType()).thenReturn(mockClass);
        // String.class.getTypeParameters() returns empty array.

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testActualTypeArguments_WithParameters() {
        // Arrange
        TypeVariable<Number> tv1 = mock(TypeVariable.class);
        TypeVariable<Number> tv2 = mock(TypeVariable.class);
        TypeVariable[] typeParameters = new TypeVariable[]{tv1, tv2};

        Type actualType1 = Integer.class;
        Type actualType2 = String.class;

        // Mocking the abstract/protected methods used in the loop
        // We use a spy or a partial mock to control the behavior of the methods called within actualTypeArguments
        GenericMetadataSupport spySupport = spy(genericMetadataSupport);

        // Since we cannot mock final methods like Class.getTypeParameters easily without PowerMock,
        // we assume the environment allows mocking the abstract rawType() to return a custom class 
        // or we mock the behavior via the spy.

        // To ensure coverage of the loop and the logic:
        when(spySupport.rawType()).thenReturn(MockContainer.class);
        // Mocking the protected method getActualTypeArgumentFor
        doReturn(actualType1).when(spySupport).getActualTypeArgumentFor(tv1);
        doReturn(actualType2).when(spySupport).getActualTypeArgumentFor(tv2);

        // Act
        Map<TypeVariable, Type> result = spySupport.actualTypeArguments();

        // Assert
        assertEquals(2, result.size());
        assertEquals(actualType1, result.get(tv1));
        assertEquals(actualType2, result.get(tv2));
    }

    /**
     * Helper class to provide type parameters for testing.
     */
    private static class MockContainer<T, U> {
    }

    // Helper to allow spy functionality on the class being tested
    private GenericMetadataSupport spy(GenericMetadataSupport target) {
        return Mockito.spy(target);
    }
}
